"use client";
import { useState } from "react";
import { CheckCircle, ShieldCheck } from "lucide-react";
type Vendor = { businessName: string; officeAddress: string; phone: string; businessRegNumber: string; bankDetails: string; logo: string; banner: string; status: string };
export function VendorProfileForm({ vendor }: { vendor: Vendor }) { const [form, setForm] = useState(vendor); const [saving, setSaving] = useState(false); const [message, setMessage] = useState(""); const update = (key: keyof Vendor, value: string) => setForm((current) => ({ ...current, [key]: value })); async function submit(event: React.FormEvent) { event.preventDefault(); setSaving(true); setMessage(""); const response = await fetch("/api/vendors", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) }); const data = await response.json(); setMessage(response.ok ? "Business profile saved." : data.error || "Unable to save profile."); setSaving(false); } return <form onSubmit={submit} className="grid gap-5 rounded-2xl border bg-white p-6 dark:bg-gray-900 md:grid-cols-2"><div className="md:col-span-2 flex items-center gap-2 rounded-xl bg-blue-50 p-3 text-sm font-bold text-blue-800 dark:bg-blue-950/30 dark:text-blue-300"><ShieldCheck className="h-5 w-5" /> Verification status: {form.status}</div><label className="grid gap-1 text-sm font-semibold">Business name<input required value={form.businessName} onChange={(e) => update("businessName", e.target.value)} className="rounded-lg border p-2 font-normal dark:bg-gray-800" /></label><label className="grid gap-1 text-sm font-semibold">Business phone<input value={form.phone} onChange={(e) => update("phone", e.target.value)} className="rounded-lg border p-2 font-normal dark:bg-gray-800" /></label><label className="grid gap-1 text-sm font-semibold md:col-span-2">Shop address<textarea required value={form.officeAddress} onChange={(e) => update("officeAddress", e.target.value)} rows={2} className="rounded-lg border p-2 font-normal dark:bg-gray-800" /></label><label className="grid gap-1 text-sm font-semibold">Business registration number<input value={form.businessRegNumber} onChange={(e) => update("businessRegNumber", e.target.value)} className="rounded-lg border p-2 font-normal dark:bg-gray-800" /></label><label className="grid gap-1 text-sm font-semibold">Payout / bank details<input value={form.bankDetails} onChange={(e) => update("bankDetails", e.target.value)} placeholder="Bank · Account name · Number" className="rounded-lg border p-2 font-normal dark:bg-gray-800" /></label><label className="grid gap-1 text-sm font-semibold">Logo URL<input value={form.logo} onChange={(e) => update("logo", e.target.value)} className="rounded-lg border p-2 font-normal dark:bg-gray-800" /></label><label className="grid gap-1 text-sm font-semibold">Banner URL<input value={form.banner} onChange={(e) => update("banner", e.target.value)} className="rounded-lg border p-2 font-normal dark:bg-gray-800" /></label><div className="md:col-span-2 flex items-center gap-3"><button disabled={saving} className="rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-bold text-white disabled:opacity-60">{saving ? "Saving..." : "Save business profile"}</button>{message && <p className={`text-sm ${message === "Business profile saved." ? "text-emerald-600" : "text-red-600"}`}>{message === "Business profile saved." && <CheckCircle className="mr-1 inline h-4 w-4" />}{message}</p>}</div></form>; }
